library(shiny)

# Intentamos instalar desde el repositorio de fuentes de Bioconductor
if (!require("RNASeqPower", quietly = TRUE)) {
  webr::install("RNASeqPower", repos = "https://bioc.r-wasm.org/latest")
}

library(RNASeqPower)

ui <- fluidPage(
  titlePanel("Calculadora RNA-Seq - Intento Final"),
  sidebarLayout(
    sidebarPanel(
      numericInput("depth", "Depth:", 100), 
      numericInput("cv", "CV:", 0.7), 
      numericInput("effect", "Effect:", 1.25), 
      numericInput("power", "Power:", 0.8), 
      numericInput("alpha", "Alpha:", 0.05),
      actionButton("btn_calcular", "CALCULAR")
    ),
    mainPanel(uiOutput("resultado"))
  )
)

server <- function(input, output) {
  calculo <- eventReactive(input$btn_calcular, {
    req(input$depth, input$cv, input$effect, input$alpha, input$power)
    RNASeqPower::rnapower(depth=input$depth, cv=input$cv, effect=input$effect, alpha=input$alpha, power=input$power)
  })
  output$resultado <- renderUI({ 
    if (input$btn_calcular == 0) return("Esperando...")
    h1(paste(ceiling(calculo()), "sujetos"))
  })
}

shinyApp(ui, server)
